// Selection only: no new layouts are created during play.
export function chooseCourse(exclude=null,random=Math.random){
  const valid=Number.isInteger(exclude)&&exclude>=1&&exclude<=COURSES.length;
  if(!valid)return 1+Math.floor(random()*COURSES.length);
  if(COURSES.length<2)return exclude;
  return 1+(exclude+Math.floor(random()*(COURSES.length-1)))%COURSES.length;
}
export function initialCourse(saved,random=Math.random){
  return Number.isInteger(saved)&&saved>=1&&saved<=COURSES.length?saved:chooseCourse(null,random);
}
